    26|// 内部调用：根据判定结果更新分数和连击数[cite: 1]
    27|void UpdateScoreAndCombo(JudgeResult result) {
    28|    uint32_t base_score = 0;
    29|    float multiplier = 1.0f;
    30|
    31|    // 1. 处理基础分与断连逻辑[cite: 1]
    32|    switch (result) {
    33|        case JUDGE_PERFECT:
    34|            base_score = 10;          // Perfect 基础分 10 分[cite: 1]
    35|            current_combo++;
    36|            break;
    37|        case JUDGE_GOOD:
    38|            base_score = 5;           // Good 基础分 5 分[cite: 1]
    39|            current_combo++;
    40|            break;
    41|        case JUDGE_MISS:
    42|            base_score = 0;           // Miss 基础分 0 分[cite: 1]
    43|            current_combo = 0;        // 断连处理[cite: 1]
    44|            break;
    45|        default:
    46|            return;
    47|    }
    48|
    49|    // 2. 更新最大连击数
    50|    if (current_combo > max_combo) {
    51|        max_combo = current_combo;
    52|    }
    53|
    54|    // 3. 计算连击加成：每满10连击，分数倍率增加10%（例如10连击×1.1，20连击×1.2）[cite: 1]
    55|    multiplier = 1.0f + ((current_combo / 10) * 0.1f);
    56|
    57|    // 4. 累加实际得分与理论最高分
    58|    total_score += (uint32_t)(base_score * multiplier);
    59|    
