// 事件数据（联合体，根据类型不同）
typedef struct {
    EventType type;
    uint32_t timestamp_ms; // 系统统一时间戳
    union {
        struct {
            uint8_t gesture_id;   // 0:上抛,1:左甩,2:右甩
            float confidence;
        } gesture;
        struct {
            uint32_t score;
            uint8_t grade;        // S/A/B/C/D
            uint16_t combo;
            float accuracy;
        } game_result;
        struct {
            uint8_t ui_state;
            uint32_t param;
        } ui;
        struct {
            uint8_t sync_type;
            uint8_t data[16];
        } sync;
    } data;
} Event;

// 事件订阅回调函数原型
typedef void (*EventCallback)(Event *evt);

// 注册订阅者（支持一对多）
int event_subscribe(EventType type, EventCallback cb);
// 取消订阅
int event_unsubscribe(EventType type, EventCallback cb);
// 发布事件（广播）
int event_publish(Event *evt);

